def report():
    plan=load(OUT/'plan.json');b=budget().read();operations=[load(p) for p in (OUT/'operations').glob('*.json')];timing=load(OUT/'timing/supervisor.json');summary=load(OUT/'evaluation/summary.json') if (OUT/'evaluation/summary.json').exists() else []
